async ({ fd: { filings, filingItems } }) => {
  const out: any = {};
  for (const tk of ["ROST", "INTU"]) {
    try {
      const f: any = await filings({ ticker: tk, filing_type: "8-K", limit: 1 });
      const acc = f.data[0].accession_number;
      const it: any = await filingItems({ ticker: tk, filing_type: "8-K", accession_number: acc });
      const s = JSON.stringify(it.data);
      out[tk] = { filing: f.data[0], text: s.slice(0, 4000) };
    } catch (e) { out[tk] = String(e).slice(0, 300); }
  }
  return out;
}
